/* @lc app=leetcode id=2930 lang=kotlin */ class Solution { fun stringCount(n: Int): Int = (1..n).fold(LongArray(12).also { it[0] = 1 }) { dp, _ -> LongArray(12).also { nd -> dp.indices.forEach { s -> (s / 6).let { l -> (s / 2 % 3).let { e -> (s % 2).let { t -> listOf(s to 23L, (6 + e * 2 + t) to 1L, (l * 6 + minOf(2, e + 1) * 2 + t) to 1L, (l * 6 + e * 2 + 1) to 1L).forEach { (ns, w) -> nd[ns] = (nd[ns] + dp[s] * w) % 1_000_000_007L } } } } } } }[11].toInt() }